import { clear, el } from "../dom.ts";
import { createFocusTrap } from "../a11y.ts";
import { icon } from "../icons.ts";
import { avatarTone, initials } from "./message_menu.ts";

export interface CallParticipantCandidate {
  id: number;
  name: string;
  username?: string | null;
  alias?: string;
  isBot?: boolean;
}

export interface CallParticipantPickerDeps {
  locale: string;
  peer: { id: number; name: string };
  loadContacts(): Promise<CallParticipantCandidate[]>;
  /** Additive server search: contacts remain visible while matching name/@username results are merged. */
  searchPeople?(query: string): Promise<CallParticipantCandidate[]>;
  onSubmit(selected: CallParticipantCandidate[]): Promise<void> | void;
  onClose?(): void;
  selfId?: number;
  maxAdditional?: number;
  searchDebounceMs?: number;
  setTimeout?(handler: () => void, delayMs: number): ReturnType<typeof globalThis.setTimeout>;
  clearTimeout?(handle: ReturnType<typeof globalThis.setTimeout>): void;
}

export interface CallParticipantPicker {
  root: HTMLElement;
  focus(): void;
  close(): void;
}

const TEXT = {
  ru: {
    title: "Добавить участников",
    lead: "Выберите контакты. Текущий звонок перейдёт в групповой.",
    current: "Уже в звонке",
    search: "Контакты или @username",
    loading: "Загружаем контакты…",
    searching: "Ищем по имени и @username…",
    empty: "Никого не найдено.",
    contactsFailed: "Не удалось загрузить контакты.",
    searchFailed: "Поиск временно недоступен. Контакты остаются в списке.",
    limit: "Можно добавить ещё не более {count} участников.",
    cancel: "Отмена",
    add: "Добавить",
    starting: "Создаём групповой звонок…",
    failed: "Не удалось создать групповой звонок.",
  },
  en: {
    title: "Add participants",
    lead: "Choose contacts. The current call will move to a group call.",
    current: "Already in the call",
    search: "Contacts or @username",
    loading: "Loading contacts…",
    searching: "Searching by name and @username…",
    empty: "No people found.",
    contactsFailed: "Could not load contacts.",
    searchFailed: "Search is temporarily unavailable. Your contacts remain listed.",
    limit: "You can add up to {count} more participants.",
    cancel: "Cancel",
    add: "Add",
    starting: "Creating the group call…",
    failed: "Could not create the group call.",
  },
} as const;

function titleOf(row: CallParticipantCandidate): string {
  return row.alias?.trim() || row.name.trim() || (row.username ? `@${row.username}` : String(row.id));
}

export function createCallParticipantPicker(deps: CallParticipantPickerDeps): CallParticipantPicker {
  const text = deps.locale.toLowerCase().startsWith("ru") ? TEXT.ru : TEXT.en;
  const max = Math.max(1, Math.min(3, deps.maxAdditional ?? 3));
  const root = el("section", {
    class: "gc-call-participant-picker",
    role: "dialog",
    "aria-modal": "true",
    "aria-labelledby": "gc-call-participant-title",
    tabindex: "-1",
  });
  const trap = createFocusTrap(root);
  const search = el("input", {
    type: "search",
    class: "gc-call-participant-search",
    placeholder: text.search,
    "aria-label": text.search,
    autocomplete: "off",
    spellcheck: "false",
  }) as HTMLInputElement;
  const list = el("div", { class: "gc-call-participant-list" });
  const status = el("p", { class: "gc-call-participant-status", role: "status", "aria-live": "polite" }, [text.loading]);
  const cancel = el("button", { type: "button", class: "gc-call-participant-cancel" }, [text.cancel]);
  const submit = el("button", { type: "button", class: "gc-call-participant-submit", disabled: true }, [
    icon("users"), text.add,
  ]);
  root.append(el("div", { class: "gc-call-participant-card" }, [
    el("header", { class: "gc-call-participant-header" }, [
      el("div", {}, [
        el("h2", { id: "gc-call-participant-title" }, [text.title]),
        el("p", {}, [text.lead]),
      ]),
      el("button", { type: "button", class: "gc-call-participant-close", "aria-label": text.cancel }, [icon("close")]),
    ]),
    el("div", { class: "gc-call-participant-current" }, [
      el("span", { class: "gc-call-participant-avatar", "data-tone": String(avatarTone(deps.peer.name)) }, [initials(deps.peer.name)]),
      el("span", {}, [el("small", {}, [text.current]), el("strong", {}, [deps.peer.name])]),
    ]),
    search,
    list,
    status,
    el("footer", { class: "gc-call-participant-footer" }, [cancel, submit]),
  ]));

  let destroyed = false;
  let busy = false;
  let contactsLoaded = false;
  let contactsFailed = false;
  let contacts: CallParticipantCandidate[] = [];
  let searched: CallParticipantCandidate[] = [];
  let searching = false;
  let searchFailed = false;
  let searchEpoch = 0;
  let searchTimer: ReturnType<typeof globalThis.setTimeout> | null = null;
  const later = deps.setTimeout ?? ((handler: () => void, delayMs: number) => globalThis.setTimeout(handler, delayMs));
  const cancelLater = deps.clearTimeout ?? ((handle: ReturnType<typeof globalThis.setTimeout>) => globalThis.clearTimeout(handle));
  const selected = new Map<number, CallParticipantCandidate>();

  const eligible = (row: CallParticipantCandidate): boolean =>
    Number.isSafeInteger(row.id)
    && row.id > 0
    && row.id !== deps.peer.id
    && row.id !== deps.selfId
    && row.isBot !== true;
  const uniqueEligible = (input: CallParticipantCandidate[]): CallParticipantCandidate[] => {
    const unique = new Map<number, CallParticipantCandidate>();
    for (const row of input) if (eligible(row) && !unique.has(row.id)) unique.set(row.id, row);
    return [...unique.values()];
  };

  const close = (): void => {
    if (destroyed) return;
    destroyed = true;
    if (searchTimer !== null) cancelLater(searchTimer);
    searchTimer = null;
    searchEpoch += 1;
    trap.release();
    root.remove();
    deps.onClose?.();
  };
  const syncSubmit = (): void => {
    submit.disabled = busy || selected.size === 0;
    submit.textContent = busy ? text.starting : `${text.add}${selected.size ? ` (${selected.size})` : ""}`;
  };
  const paint = (): void => {
    clear(list);
    const query = search.value.trim().toLocaleLowerCase();
    const needle = query.replace(/^@+/, "");
    const matches = (row: CallParticipantCandidate): boolean => [row.alias ?? "", row.name, row.username ?? ""]
      .some((value) => value.toLocaleLowerCase().includes(needle));
    const local = query ? contacts.filter(matches) : contacts;
    const visible = uniqueEligible([...local, ...searched]);

    if (visible.length === 0) {
      status.hidden = false;
      status.textContent = searching
        ? text.searching
        : searchFailed
          ? text.searchFailed
          : contactsFailed
            ? text.contactsFailed
            : contactsLoaded
              ? text.empty
              : text.loading;
      return;
    }
    status.hidden = !searching && !searchFailed;
    status.textContent = searching ? text.searching : searchFailed ? text.searchFailed : "";
    for (const row of visible) {
      const label = titleOf(row);
      const checkbox = el("input", { type: "checkbox", "aria-label": label }) as HTMLInputElement;
      checkbox.checked = selected.has(row.id);
      checkbox.addEventListener("change", () => {
        if (busy) return;
        if (checkbox.checked) {
          if (selected.size >= max) {
            checkbox.checked = false;
            status.hidden = false;
            status.textContent = text.limit.replace("{count}", String(max));
            return;
          }
          selected.set(row.id, row);
        } else {
          selected.delete(row.id);
        }
        syncSubmit();
      });
      list.append(el("label", { class: "gc-call-participant-row" }, [
        el("span", { class: "gc-call-participant-avatar", "data-tone": String(avatarTone(label)) }, [initials(label)]),
        el("span", { class: "gc-call-participant-copy" }, [
          el("strong", {}, [label]),
          el("small", {}, [row.username ? `@${row.username}` : ""]),
        ]),
        checkbox,
      ]));
    }
  };

  const scheduleSearch = (): void => {
    if (searchTimer !== null) cancelLater(searchTimer);
    searchTimer = null;
    const query = search.value.trim();
    const epoch = ++searchEpoch;
    searched = [];
    searchFailed = false;
    if (!deps.searchPeople || query.replace(/^@+/, "").length < 2) {
      searching = false;
      paint();
      return;
    }
    searching = true;
    paint();
    searchTimer = later(() => {
      searchTimer = null;
      void deps.searchPeople!(query).then((rows) => {
        if (destroyed || epoch !== searchEpoch) return;
        searched = uniqueEligible(rows);
        searching = false;
        searchFailed = false;
        paint();
      }, () => {
        if (destroyed || epoch !== searchEpoch) return;
        searched = [];
        searching = false;
        searchFailed = true;
        paint();
      });
    }, Math.max(0, deps.searchDebounceMs ?? 250));
  };

  search.addEventListener("input", scheduleSearch);
  cancel.addEventListener("click", close);
  (root.querySelector(".gc-call-participant-close") as HTMLButtonElement | null)?.addEventListener("click", close);
  root.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || busy) return;
    event.preventDefault();
    close();
  });
  submit.addEventListener("click", () => {
    if (busy || selected.size === 0) return;
    busy = true;
    search.disabled = true;
    cancel.disabled = true;
    status.hidden = false;
    status.textContent = text.starting;
    syncSubmit();
    void Promise.resolve(deps.onSubmit([...selected.values()])).then(close, () => {
      if (destroyed) return;
      busy = false;
      search.disabled = false;
      cancel.disabled = false;
      status.hidden = false;
      status.textContent = text.failed;
      syncSubmit();
    });
  });

  void deps.loadContacts().then((rows) => {
    if (destroyed) return;
    contactsLoaded = true;
    contactsFailed = false;
    contacts = uniqueEligible(rows);
    paint();
  }, () => {
    if (destroyed) return;
    contactsLoaded = true;
    contactsFailed = true;
    contacts = [];
    paint();
  });

  return { root, focus: () => trap.activate(), close };
}
